    let is_new_bin = bin_residual == bin_capacity;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base score: favor smaller residuals but apply a non-linear cost to discourage medium-sized "dead" gaps
    let mut score = post * 1.05;

    // 1. Precise Fit Optimization: Reward perfect/near-perfect fits
    if post == 0.0 {
        score -= 225.0;
    } else if post < 7.0 {
        // High reward for tight fits, but modulated by the "trap" probability
        score -= 120.0 + (7.0 - post) * 14.0;
    }

    // 2. Predictive Lookahead: Refined coupling
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual >= next_item_size {
            // Reward bins that fit the next item with minimal slack
            let slack = (post_residual - next_item_size) as f64;
            score -= 75.0 / (1.0 + slack * 0.1);
        } else {
            // Penalize bins that block the next item significantly
            score += (next - post).powf(1.2) * 9.0;
        }
    }

    // 3. Dynamic New-Bin Thresholding
    if is_new_bin {
        // Increase barrier to opening new bins as the stream matures
        let new_bin_base_penalty = 150.0 + (progress * 140.0);
        let congestion_penalty = (open_bins_count as f64 * 2.5).min(110.0);

        if fitting_bins_count > 0 {
            score += new_bin_base_penalty + congestion_penalty;
        } else {
            score -= 75.0; // Force open if no options exist
        }
    } else {
        // 4. Density Balancing & Anti-Fragmentation
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.6;

        // Anti-fragmentation: Penalize small residuals that are likely to become unfillable
        // Adjusted to reflect common item size distributions
        if post > 0.0 && post < 8.0 {
            score += 35.0 - (post * 2.0); 
        }

        // Prune high-residual bins when we have many choices
        if fitting_bins_count > 3 {
            score += post.powf(1.5) * 1.1;
        }
    }

    // 5. Global Compaction Phase
    // Aggressive consolidation in the final 15% of the stream
    if progress > 0.85 {
        score += post.powf(2.2) * 1.8;
    } else if progress < 0.15 {
        // Early-stage: encourage lower residual variance to keep options open
        score -= post * 0.3;
    }

    score
}

