    // 1. Dead Space Penalty: If the post_residual is small (1-9), it is likely unusable.
    // We heavily penalize creating gaps that cannot accommodate the smallest possible items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item can fit in the current post_residual, 
    // prioritize this bin to maximize bin density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins (bin_residual == bin_capacity)
    // unless the fit is extremely tight (Best Fit behavior).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales with the number of existing open bins
        // to prevent fragmentation.
        score += 25.0 + (open_bins_count as f64 * 2.0);
    } else {
        // 4. Tightness Reward: Favor bins where the item fits snugly.
        // We subtract the post_residual to favor smaller remaining space (Best Fit).
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 5. Global Efficiency: As we approach the end of the stream, 
    // become more aggressive about filling existing bins to avoid leftover bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 5.0);

    // 6. Last Chance Logic: If this is the only bin that fits the item, 
    // reward placing it here to avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let post = post_residual as f64;

    // Base score: Increase weight on post-residual to prioritize tighter packing
    let mut score = post * 1.45;

    // 1. Precise Fit Optimization: Aggressive reward for near-perfect fills
    if post == 0.0 {
        score -= 310.0;
    } else if post < 9.0 {
        score -= 160.0 + (9.0 - post) * 14.0;
    }

    // 2. Predictive Lookahead: Refine to account for the probability that small gaps are unusable
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that maintain capacity for the next item plus a small slack
            let buffer = (post_residual - next_item_size) as f64;
            score -= 95.0 * (1.0 / (1.0 + buffer * 0.18));
        } else {
            // Penalize bins that cannot accommodate the upcoming item, scaling with gap mismatch
            score += (next_item_size as f64 - post).powf(1.25) * 8.5;
        }
    }

    // 3. Dynamic New-Bin Thresholding
    if is_new_bin {
        // As stream progresses, opening new bins becomes increasingly expensive
        let new_bin_base_penalty = 190.0 + (progress * 140.0);
        let congestion_penalty = (open_bins_count as f64 * 2.5).min(110.0);

        if fitting_bins_count > 0 {
            score += new_bin_base_penalty + congestion_penalty;
        } else {
            score -= 80.0; 
        }
    } else {
        // 4. Density Balancing & Anti-Fragmentation
        // Penalize bins that create "unfillable" gaps (residuals < 6)
        if post > 0.0 && post < 6.0 {
            score += 65.0;
        }

        // Penalize deviation from mean_residual to keep bin distribution uniform
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.85;

        // If we have many options, prune high-residual bins to consolidate
        if fitting_bins_count > 2 {
            score += post.powf(1.6) * 1.25;
        }
    }

    // 5. Global Compaction Phase
    // Late-stage: prioritize closing bins over flexibility by penalizing remaining capacity
    if progress > 0.7 {
        score += post.powf(2.6) * 2.8;
    } else if progress < 0.1 {
        // Early-stage: allow more variance to build a diverse set of open bins
        score -= post * 0.35;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
