    if post == 0.0 {
        score -= 310.0;
    } else if post < 6.0 {
        score -= 165.0 + (6.0 - post) * 18.0;
    }

    // 2. Predictive Lookahead: Focused on "Next-Item" fit probability.
    // If we can fit the next item, we reward the bin proportional to the remaining slack.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward bins that leave *just enough* room for the next item (avoiding fragmentation)
            score -= 95.0 / (1.0 + slack.sqrt() * 0.4);
        } else {
            // Penalize bins that cannot fit the next item, scaling by the severity of the deficit
            score += (next_item_size - post_residual) as f64 * 8.2;
        }
    }

    // 3. New Bin Threshold: Dynamic penalty based on current "open bin density".
    // We want to force consolidation when we have too many under-utilized bins.
    if is_new_bin {
        let density_penalty = (open_bins_count as f64 / (1.0 + progress * 5.0)) * 24.0;
        let base_new_bin_cost = 190.0 + (progress * 140.0);

        if fitting_bins_count > 0 {
            score += base_new_bin_cost + density_penalty;
        } else {
            score -= 85.0; // Essential to open a new bin if nothing else fits
        }
    } else {
        // 4. Anti-Fragmentation: Target "Dead Zones" (small residuals that block future items)
        // If residual is small but > 0, it's often better to avoid unless it's a perfect fit.
        if post > 0.0 && post < 7.0 {
            score += 65.0 * (1.0 - post / 7.0);
        }

        // Variance control: Keep bins near the mean_residual to prevent extreme outliers
        score += (post - mean_residual).abs() * 0.85;

        // If many fitting bins exist, heavily penalize high-residual choices to force consolidation.
        if fitting_bins_count > 3 {
            score += post.powf(1.6) * 1.3;
        }
