    // 5. Global Compaction Phase: Aggressive closing in final 20% of stream
    if progress > 0.80 {
        score += post.powf(2.5) * 3.5;
    } else if progress < 0.10 {
        // Early phase: allow more flexibility, favor larger remaining capacity to keep options open
        score -= post * 0.35;
    }

    score
}

