    let density_balance = (post - mean_residual).powi(2) * 0.5;

    // Discourage opening new bins unless the current fit is extremely poor
    // As progress increases, we become more conservative (higher penalty for new bin)
    let new_bin_penalty = if bin_residual == bin_capacity {
