    // If the post_residual is small but not zero, it's often a "sliver" that wastes space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
