    }

    // 4. Fitting Constraint: If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 5. Residual Alignment: Attempt to keep bins uniform. 
    // Penalize if the post_residual deviates significantly from the mean_residual of open bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // 6. Modulo Harmonic: Prefer filling bins to specific "harmonic" thresholds (e.g., 25, 50, 75).
    // This creates "bins" of items that are likely to sum to near-capacity.
    let fill_level = bin_capacity - post_residual;
    if fill_level % 25 == 0 {
        score -= 10.0;
    }

    score
}

