    let is_new_bin = bin_residual == bin_capacity;
    let post = post_residual as f64;

    // 1. Core objective: Higher base weight on post_residual to favor tight packing.
    let mut score = post * 1.65;

    // 2. Exact Fit Optimization: Exponentially reward perfect and near-perfect matches.
    if post == 0.0 {
        score -= 450.0;
    } else if post < 4.0 {
        score -= 220.0 + (4.0 - post) * 20.0;
    }

    // 3. Predictive Lookahead: Enhanced to force readiness for next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item while minimizing wasted slack.
            let slack = (post_residual - next_item_size) as f64;
            score -= 130.0 * (1.0 / (1.0 + slack * 0.08));
        } else {
            // Aggressive penalty for creating "dead zones" that cannot fit the next item.
            score += (next_item_size as f64 - post).powf(1.4) * 9.5;
        }
    }

    // 4. Dynamic New-Bin Management:
    if is_new_bin {
        // Increase cost of new bins dynamically to force utilization of existing volume.
        let penalty = 210.0 + (progress * 180.0);
        let congestion = (open_bins_count as f64 * 4.0).min(150.0);

        if fitting_bins_count > 0 {
            score += penalty + congestion;
        } else {
            // If no fit exists, force creation but bias toward lower-residual containers.
            score -= 60.0;
        }
    } else {
        // 5. Anti-Fragmentation:
        // Penalize small unusable residuals that contribute to fragmentation.
        if post > 0.0 && post < 8.0 {
            score += 85.0;
        }

        // Penalize deviation from mean_residual to homogenize bin fill rates.
        score += (post - mean_residual).abs() * 1.1;

        // If many bins fit, perform aggressive consolidation by penalizing high-residual bins.
        if fitting_bins_count > 2 {
            score += post.powf(1.8) * 1.5;
        }
    }

    // 6. Global Compaction Phase:
    // Tighten constraints on final 20% to eliminate straggler bins.
    if progress > 0.8 {
        score += post.powf(2.8) * 4.5;
    } else if progress < 0.1 {
        // Early stage: prioritize bin availability over immediate compactness.
        score -= post * 0.5;
    }

    score
}

