        if bin_residual as f64 > mean_residual {
            score += (bin_residual as f64 - mean_residual).powf(1.7) * 1.05;
        }
    }

    // 6. Terminal Compaction: Increased intensity in the final 10% to force perfect fits
    if progress > 0.90 {
        score += (post_residual as f64).powf(2.5) * (12.0 + progress * 20.0);
    } else {
        score += progress * (post_residual as f64 * 0.75);
    }

    // 7. Splinter Prevention: Penalize residuals in the "unfillable" range [1, 12]
    // Heuristic: Items are up to 100, but most are smaller; 12 is a common "dead" threshold
    if post_residual > 0 && post_residual <= 12 {
        score += 85.0 + (12.0 - post_residual as f64) * 22.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #486: Harmonic-Residual Balancing
    // We prioritize bins that create "high-density" residues (small post_residual)
    // but penalize residues that are too small to fit common future items (10-30 range).

    let mut score = post_residual as f64;

    // 1. If this is a new bin, apply a threshold penalty to discourage opening new bins
    // unless the current open bins are extremely poor fits.
    if bin_residual == bin_capacity {
        score += 25.0; 
    }

    // 2. Harmonic penalty: Penalize residues in the "dead zone" (1-9) where 
    // it's unlikely to fit any future item, but favor residues that are 
    // multiples of the next_item_size or common item denominators.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 3. Lookahead integration: If next_item_size is large, favor bins that 
    // have exactly enough space or are already quite empty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0; // Strong preference for bins that can accommodate next item
        } else {
            score += 2.0; // Slight penalty for blocking the next item
        }
    }

    // 4. Density Balancing: If we have many open bins, penalize larger post_residuals
    // to force consolidation into fewer active bins.
    let consolidation_factor = (open_bins_count as f64) * 0.5;
    score += (post_residual as f64) * 0.1 * consolidation_factor;

    // 5. Fitting constraint: If this is the last bin that can fit the item, 
    // we heavily reward placing it here to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Mean-Residual normalization: Avoid creating bins that deviate significantly 
    // from the current average residual (encourages uniform filling).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // 1. Predictive Lookahead: Refined for tighter bin packing
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 82.0; 
        } else if post_residual < next_item_size {
            score += 172.0 + (next_item_size - post_residual) as f64 * 14.2;
        } else {
            let headroom = (post_residual - next_item_size) as f64;
            score -= 64.0 / (1.0 + (headroom * 0.38).sqrt());
            if headroom < 6.0 { score -= 55.0; }
        }
    }

    // 2. Adaptive New Bin Logic: Tightened sprawl control
    if bin_residual == bin_capacity {
        let base_threshold = 32.0;
        let dynamic_pressure = (mean_residual * 0.72) + (open_bins_count as f64 * 1.45) + (progress * 132.0);
        score = base_threshold + dynamic_pressure;
    } else {
        // 3. Density-based Weighting: Adjusted for variance sensitivity
        score += (post_residual as f64 - mean_residual) * 1.88;

        // 4. Criticality: Stronger reward for filling near-capacity bins
        if fitting_bins_count <= 3 {
            score -= 158.0 / (fitting_bins_count as f64 + 0.4);
        }

        // 5. Anti-Fragmentation: Non-linear fill ratio optimization (enhanced pressure)
        let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        let open_bias = if open_bins_count > 5 { 132.0 } else { 62.0 };
        score -= (fill_ratio.powf(3.1) * open_bias);

        // Compaction pressure: Penalize residuals that exceed mean with higher curvature
        if bin_residual as f64 > mean_residual {
            score += (bin_residual as f64 - mean_residual).powf(1.65) * 0.95;
        }
    }

    // 6. Terminal Compaction: Aggressive endgame closing
    if progress > 0.85 {
        score += (post_residual as f64).powf(2.25) * (10.0 + progress * 15.0);
    } else {
        score += progress * (post_residual as f64 * 0.62);
    }

    // 7. Splinter Prevention: Aggressive penalty for unfillable "dead zones"
    if post_residual > 0 && post_residual <= 11 {
        score += 78.0 + (11.0 - post_residual as f64) * 22.0;
    }

    // 8. Global Mean Anchor: Final dampener for outlier bins
    score += (post_residual as f64 - (mean_residual * 0.9)).abs() * 0.25;

    score
}
